CREATE TABLE growth_reports(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,batch_id TEXT NOT NULL,student_id TEXT NOT NULL,teacher_id TEXT,report_class_id TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL CHECK(status IN('draft','ready','published')),progress TEXT NOT NULL CHECK(progress IN('not_started','draft','ready','published')),doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),context_json TEXT NOT NULL CHECK(json_valid(context_json)),published_revision_id TEXT,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,batch_id,student_id),FOREIGN KEY(tenant_id,batch_id) REFERENCES growth_batches(tenant_id,id));
